namespace SHOU.Launcher.Core.Content;

/// <summary>Validate containment without guessing which game data a modpack may need.</summary>
internal static class PackPayloadPath
{
    internal static void Validate(string path)
    {
        ModrinthPackArchive.SafeRelative(path);
        // This file is generated by the import transaction, not supplied by a pack.
        if (ContentInstallFiles.PathKey(path.Split('/')[0]) == ContentInstallFiles.PathKey(ContentInstallFiles.ManifestName))
            throw new InvalidDataException("整合包内容与启动器生成的安装清单冲突：" + path);
    }

    internal static bool DownloadUri(Uri uri) => uri.IsAbsoluteUri && uri.Scheme is "http" or "https" &&
        uri.Host.Length > 0 && uri.UserInfo.Length == 0 && uri.Fragment.Length == 0;
}
